'use client';

import Image from "next/image";
import { motion } from "framer-motion";
import { rajdhani, orbitron } from "../fonts";
import { FaFacebook, FaInstagram, FaDiscord, FaUser, FaEnvelope, FaPhone, FaGraduationCap, FaGamepad } from 'react-icons/fa';
import Navbar from '../components/Navbar';
import { useState } from 'react';

export default function DevenirMembre() {
  const [formData, setFormData] = useState({
    nom: '',
    prenom: '',
    email: '',
    telephone: '',
    ecole: '',
    niveau: '',
    jeuxPreferes: '',
    competences: '',
    motivation: '',
    password: '',
    confirmPassword: ''
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (formData.password !== formData.confirmPassword) {
      alert('Les mots de passe ne correspondent pas!');
      return;
    }

    try {
      const response = await fetch('/api/membres', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        alert('Inscription réussie! Bienvenue dans la famille GameLab! 🎮');
        // Reset form
        setFormData({
          nom: '',
          prenom: '',
          email: '',
          telephone: '',
          ecole: '',
          niveau: '',
          jeuxPreferes: '',
          competences: '',
          motivation: '',
          password: '',
          confirmPassword: ''
        });
      } else {
        alert('Erreur lors de l\'inscription. Veuillez réessayer.');
      }
    } catch (error) {
      console.error('Erreur:', error);
      alert('Erreur de connexion. Veuillez réessayer.');
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  return (
    <div className="flex flex-col min-h-screen relative">
      {/* Background */}
      <div className="fixed inset-0 z-0">
        <img 
          src="/background.jpg" 
          alt="Background"
          className="w-full h-full object-cover"
        />
        <div className="absolute inset-0 bg-black/75"></div>
      </div>

      {/* Header */}
      <header className="relative overflow-hidden flex flex-col w-full z-10">
        <div className="flex items-center justify-between w-full py-4 px-6 bg-gradient-to-r from-purple-950 to-purple-700">
          <div className="flex items-center gap-3">
            <Image width={80} height={80} alt="GameLab Logo" src="/logo.jpeg" />
            <h1 className={`${rajdhani.className} text-white text-2xl sm:text-3xl font-bold tracking-wider`}>
              GAMELAB
            </h1>
          </div>
          <div className="hidden lg:flex">
            <Navbar />
          </div>
          <div className="flex gap-4">
            <a href="https://www.facebook.com/gamelab.inpt.7" target="_blank" rel="noopener noreferrer" className="text-white hover:text-purple-300 transition-colors duration-300">
              <FaFacebook size={32} />
            </a>
            <a href="https://www.instagram.com/gamelabinpt/" target="_blank" rel="noopener noreferrer" className="text-white hover:text-purple-300 transition-colors duration-300">
              <FaInstagram size={32} />
            </a>
            <a href="https://discord.gg/kqSCjXQJ" target="_blank" rel="noopener noreferrer" className="text-white hover:text-purple-300 transition-colors duration-300">
              <FaDiscord size={32} />
            </a>
          </div>
        </div>
      </header>

      {/* Form */}
      <main className="flex-1 px-6 py-16 relative z-10">
        <div className="max-w-4xl mx-auto">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="bg-gradient-to-br from-purple-900/40 to-black/60 backdrop-blur-md rounded-2xl p-8 border border-purple-500/30"
          >
            <h2 className={`${orbitron.className} text-white text-4xl font-bold mb-4 text-center`}>
              Devenir Membre du GameLab
            </h2>
            <p className="text-gray-300 text-center mb-8">
              Rejoins la plus grande communauté gaming de l'INPT! 🚀
            </p>

            {/* Avantages */}
            <div className="bg-gradient-to-r from-purple-600/20 to-pink-600/20 border border-purple-500/30 rounded-xl p-6 mb-8">
              <h3 className={`${rajdhani.className} text-white text-2xl font-bold mb-4`}>
                Pourquoi devenir membre?
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {[
                  'Accès prioritaire aux événements',
                  'Réductions sur les tournois',
                  'Accès à la salle gaming',
                  'Formations GameDev gratuites',
                  'Networking avec d\'autres gamers',
                  'Participation aux décisions du club'
                ].map((avantage, index) => (
                  <div key={index} className="flex items-center gap-3">
                    <div className="w-2 h-2 bg-purple-500 rounded-full"></div>
                    <span className="text-gray-300">{avantage}</span>
                  </div>
                ))}
              </div>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Informations Personnelles */}
              <div>
                <h3 className={`${rajdhani.className} text-white text-xl font-bold mb-4`}>
                  Informations Personnelles
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label htmlFor="nom" className="block text-white font-semibold mb-2">
                      <FaUser className="inline mr-2" />
                      Nom *
                    </label>
                    <input
                      type="text"
                      id="nom"
                      name="nom"
                      value={formData.nom}
                      onChange={handleChange}
                      required
                      className="w-full px-4 py-3 bg-black/50 border border-purple-500/30 rounded-lg text-white focus:outline-none focus:border-purple-500 transition-colors"
                    />
                  </div>
                  <div>
                    <label htmlFor="prenom" className="block text-white font-semibold mb-2">
                      Prénom *
                    </label>
                    <input
                      type="text"
                      id="prenom"
                      name="prenom"
                      value={formData.prenom}
                      onChange={handleChange}
                      required
                      className="w-full px-4 py-3 bg-black/50 border border-purple-500/30 rounded-lg text-white focus:outline-none focus:border-purple-500 transition-colors"
                    />
                  </div>
                </div>
              </div>

              {/* Contact */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label htmlFor="email" className="block text-white font-semibold mb-2">
                    <FaEnvelope className="inline mr-2" />
                    Email *
                  </label>
                  <input
                    type="email"
                    id="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    required
                    className="w-full px-4 py-3 bg-black/50 border border-purple-500/30 rounded-lg text-white focus:outline-none focus:border-purple-500 transition-colors"
                  />
                </div>
                <div>
                  <label htmlFor="telephone" className="block text-white font-semibold mb-2">
                    <FaPhone className="inline mr-2" />
                    Téléphone *
                  </label>
                  <input
                    type="tel"
                    id="telephone"
                    name="telephone"
                    value={formData.telephone}
                    onChange={handleChange}
                    required
                    className="w-full px-4 py-3 bg-black/50 border border-purple-500/30 rounded-lg text-white focus:outline-none focus:border-purple-500 transition-colors"
                  />
                </div>
              </div>

              {/* Études */}
              <div>
                <h3 className={`${rajdhani.className} text-white text-xl font-bold mb-4`}>
                  Informations Académiques
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label htmlFor="ecole" className="block text-white font-semibold mb-2">
                      <FaGraduationCap className="inline mr-2" />
                      École/Université *
                    </label>
                    <input
                      type="text"
                      id="ecole"
                      name="ecole"
                      value={formData.ecole}
                      onChange={handleChange}
                      required
                      placeholder="Ex: INPT"
                      className="w-full px-4 py-3 bg-black/50 border border-purple-500/30 rounded-lg text-white focus:outline-none focus:border-purple-500 transition-colors"
                    />
                  </div>
                  <div>
                    <label htmlFor="niveau" className="block text-white font-semibold mb-2">
                      Niveau d'études *
                    </label>
                    <select
                      id="niveau"
                      name="niveau"
                      value={formData.niveau}
                      onChange={handleChange}
                      required
                      className="w-full px-4 py-3 bg-black/50 border border-purple-500/30 rounded-lg text-white focus:outline-none focus:border-purple-500 transition-colors"
                    >
                      <option value="">Sélectionner</option>
                      <option value="1ere-annee">1ère année</option>
                      <option value="2eme-annee">2ème année</option>
                      <option value="3eme-annee">3ème année</option>
                      <option value="master">Master</option>
                      <option value="doctorat">Doctorat</option>
                    </select>
                  </div>
                </div>
              </div>

              {/* Gaming Profile */}
              <div>
                <h3 className={`${rajdhani.className} text-white text-xl font-bold mb-4`}>
                  <FaGamepad className="inline mr-2" />
                  Profil Gaming
                </h3>
                <div className="space-y-6">
                  <div>
                    <label htmlFor="jeuxPreferes" className="block text-white font-semibold mb-2">
                      Jeux préférés
                    </label>
                    <input
                      type="text"
                      id="jeuxPreferes"
                      name="jeuxPreferes"
                      value={formData.jeuxPreferes}
                      onChange={handleChange}
                      placeholder="Ex: Valorant, League of Legends, FIFA..."
                      className="w-full px-4 py-3 bg-black/50 border border-purple-500/30 rounded-lg text-white focus:outline-none focus:border-purple-500 transition-colors"
                    />
                  </div>
                  <div>
                    <label htmlFor="competences" className="block text-white font-semibold mb-2">
                      Compétences particulières
                    </label>
                    <input
                      type="text"
                      id="competences"
                      name="competences"
                      value={formData.competences}
                      onChange={handleChange}
                      placeholder="Ex: Streaming, Game Design, Développement..."
                      className="w-full px-4 py-3 bg-black/50 border border-purple-500/30 rounded-lg text-white focus:outline-none focus:border-purple-500 transition-colors"
                    />
                  </div>
                </div>
              </div>

              {/* Motivation */}
              <div>
                <label htmlFor="motivation" className="block text-white font-semibold mb-2">
                  Pourquoi veux-tu rejoindre GameLab? *
                </label>
                <textarea
                  id="motivation"
                  name="motivation"
                  value={formData.motivation}
                  onChange={handleChange}
                  required
                  rows={4}
                  placeholder="Parle-nous de ta passion pour le gaming et ce que tu espères apporter au club..."
                  className="w-full px-4 py-3 bg-black/50 border border-purple-500/30 rounded-lg text-white focus:outline-none focus:border-purple-500 transition-colors resize-none"
                />
              </div>

              {/* Mot de passe */}
              <div>
                <h3 className={`${rajdhani.className} text-white text-xl font-bold mb-4`}>
                  Créer votre compte
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label htmlFor="password" className="block text-white font-semibold mb-2">
                      Mot de passe *
                    </label>
                    <input
                      type="password"
                      id="password"
                      name="password"
                      value={formData.password}
                      onChange={handleChange}
                      required
                      minLength={8}
                      className="w-full px-4 py-3 bg-black/50 border border-purple-500/30 rounded-lg text-white focus:outline-none focus:border-purple-500 transition-colors"
                    />
                  </div>
                  <div>
                    <label htmlFor="confirmPassword" className="block text-white font-semibold mb-2">
                      Confirmer le mot de passe *
                    </label>
                    <input
                      type="password"
                      id="confirmPassword"
                      name="confirmPassword"
                      value={formData.confirmPassword}
                      onChange={handleChange}
                      required
                      minLength={8}
                      className="w-full px-4 py-3 bg-black/50 border border-purple-500/30 rounded-lg text-white focus:outline-none focus:border-purple-500 transition-colors"
                    />
                  </div>
                </div>
                <p className="text-gray-400 text-sm mt-2">
                  Le mot de passe doit contenir au moins 8 caractères
                </p>
              </div>

              {/* Submit */}
              <motion.button
                type="submit"
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                className="w-full px-8 py-4 bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white font-bold rounded-lg transition-all duration-300 uppercase tracking-wider text-lg"
              >
                Créer mon compte membre
              </motion.button>
            </form>

            <div className="mt-6 text-center">
              <p className="text-gray-400 text-sm">
                Déjà membre?{' '}
                <a href="/login" className="text-purple-400 hover:text-purple-300 underline">
                  Se connecter
                </a>
              </p>
            </div>
          </motion.div>
        </div>
      </main>
    </div>
  );
}
